 78	    /**
 79	     * Tries to find a prey in one of the neighboring cell. If a prey is found, it is eaten and its location is returned.
 80	     *
 81	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
 82	     * @return (Location) the location of the eaten prey, null if no prey was found.
 83	     */
 84	    private Location findFoodAndEat(List<Animal> neighboringAnimals)
 85	    {
 86	        for (Animal animal : neighboringAnimals) {
 87	            if (!(animal instanceof Predator)) {
 88	                Location preyLocation = animal.getLocation();
 89	                animal.setDead();
 90	                foodLevel += animal.getNutritionalValue();
 91	                return preyLocation;
 92	            }
 93	        }
 94	        // No food found
 95	        return null;
 96	    }
