 98	    /**
 99	     * Check if predator if under attack from a horde of another species of predator. If a horde is attacking it and the horde's strength
100	     * is greater than the predator's one, the horde members eat it.
101	     *
102	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
103	     */
104	    private void checkForAttack(List<Animal> neighboringAnimals)
105	    {
106	        HashMap<String, List<Predator>> hordesBySpecies = new HashMap<>();
107	
108	        for (Animal animal : neighboringAnimals) {
109	            if (animal instanceof Predator) {
110	                Predator predator = (Predator) animal;
111	                if (!predator.getName().equals(getName())) {
112	                    List<Predator> hordeMembers = hordesBySpecies.get(predator.getName());
113	                    if (hordeMembers == null) {
114	                        hordeMembers = new ArrayList<>();
115	                        hordesBySpecies.put(predator.getName(), hordeMembers);
116	                    }
117	                    hordeMembers.add(predator);
118	                }
119	            }
120	        }
121	
122	        for (List<Predator> hordeMembers : hordesBySpecies.values()) {
123	            if (calculateHordeStrength(hordeMembers) > strength) {
124	                attackedByHorde(hordeMembers);
125	                return;
126	            }
127	        }
128	    }
