130	    /**
131	     * Calculate the combined strength of a horde.
132	     *
133	     * @param hordeMembers the predators in the horde.
134	     * @return the total strength.
135	     */
136	    private int calculateHordeStrength(List<Predator> hordeMembers)
137	    {
138	        int totalStrength = 0;
139	        for (Predator predator : hordeMembers) {
140	            totalStrength += predator.getStrength();
141	        }
142	        return totalStrength;
143	    }
