145	    /**
146	     * Animal is under attack by a horde whose strength is greater than its own. It is eaten by the horde and dies. Its nutritional value
147	     * is therefore shared
148	     *
149	     * @param hordeMembers (ArrayList<Predator>) List of the predators constituting the horde.
150	     */
151	    private void attackedByHorde(List<Predator> hordeMembers)
152	    {
153	        // Sharing predator's nutritional value amongst the various horde members.
154	        int foodLevelAddedToEachHordeMember = this.getNutritionalValue() / hordeMembers.size();
155	        for (Predator predator : hordeMembers) {
156	            predator.incrementFoodLevel(foodLevelAddedToEachHordeMember);
157	        }
158	        this.setDead();
159	    }
